"""Worker pool used by the report rollups.

A single lock guards the queue and the reports so no call site can hold
one lock while waiting on the other. The previous revision had two locks
and acquired them in opposite orders (handoff: report then queue, claim:
queue then report), which deadlocked under concurrent use.
"""
import threading


class Pool:
    def __init__(self):
        self._lock = threading.Lock()
        self._queue = []
        self._reports = {}

    def submit(self, job):
        with self._lock:
            self._queue.append(job)

    def handoff(self, worker_id, report):
        # Record the report and claim the next job atomically, so a worker
        # never holds two jobs at once.
        with self._lock:
            self._reports[worker_id] = report
            if self._queue:
                return self._queue.pop(0)
        return None

    def claim(self, worker_id):
        with self._lock:
            self._reports.setdefault(worker_id, None)
            if self._queue:
                return self._queue.pop(0)
        return None

"""Real unit tests for the reportd worker pool (src/worker.py).

Run with:  python3 -m unittest -v tests.test_worker
          python3 tests/test_worker.py          (same thing, verbose)

These exercise the pool concurrently. test_deadlock_handoff_vs_claim is a
regression test for the two-lock deadlock that existed in the previous
revision of src/worker.py, where handoff() took _report_lock before
_queue_lock while claim() took _queue_lock before _report_lock. Any
re-introduction of that ordering will reliably hang this test, which the
runner converts into a reported timeout.
"""
import os
import sys
import threading
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))

from src.worker import Pool


class TestSubmitClaim(unittest.TestCase):
    def test_claim_returns_submitted_jobs_in_fifo_order(self):
        pool = Pool()
        for i in range(5):
            pool.submit(i)
        got = [pool.claim("w0") for _ in range(5)]
        self.assertEqual(got, [0, 1, 2, 3, 4])
        self.assertIsNone(pool.claim("w0"))

    def test_claim_on_empty_queue_returns_none(self):
        self.assertIsNone(Pool().claim("w0"))

    def test_submit_is_visible_to_multiple_workers(self):
        pool = Pool()
        for i in range(20):
            pool.submit(i)
        results = []
        results_lock = threading.Lock()

        def worker():
            while True:
                job = pool.claim("w")
                if job is None:
                    return
                with results_lock:
                    results.append(job)

        threads = [threading.Thread(target=worker) for _ in range(4)]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=10)
        self.assertTrue(all(not t.is_alive() for t in threads),
                        "a worker did not finish in time")
        self.assertEqual(sorted(results), list(range(20)))


class TestHandoff(unittest.TestCase):
    def test_handoff_records_report_and_claims_next_job(self):
        pool = Pool()
        pool.submit("job-a")
        pool.submit("job-b")
        pool.handoff("w0", "report-0")
        nxt = pool.handoff("w1", "report-1")
        self.assertEqual(nxt, "job-b")

    def test_handoff_reports_are_overwritten_per_worker(self):
        pool = Pool()
        pool.submit("x")
        pool.handoff("w0", "first")
        pool.handoff("w0", "second")
        pool.handoff("w0", "third")
        self.assertEqual(pool._reports["w0"], "third")

    def test_handoff_on_empty_queue_returns_none(self):
        pool = Pool()
        self.assertIsNone(pool.handoff("w0", "report"))


class TestConcurrency(unittest.TestCase):
    def test_deadlock_handoff_vs_claim(self):
        """Regression test for the opposite lock-order deadlock.

        One worker hammers handoff() while another hammers claim(). With
        the previous two-lock implementation these acquire the locks in
        opposite orders and deadlock within a handful of iterations; with
        the single-lock implementation all of them complete.
        """
        pool = Pool()
        for i in range(50):
            pool.submit(i)
        stop = threading.Event()

        def handoff_worker():
            while not stop.is_set():
                if pool.handoff("h", "r") is None:
                    return

        def claim_worker():
            while not stop.is_set():
                if pool.claim("c") is None:
                    return

        threads = []
        for _ in range(2):
            threads.append(threading.Thread(target=handoff_worker))
            threads.append(threading.Thread(target=claim_worker))
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=10)
        for t in threads:
            self.assertFalse(t.is_alive(), "deadlock: worker did not finish")

    def test_mixed_submit_handoff_claim(self):
        """Submitters, handoffers and claimers run at the same time."""
        pool = Pool()
        n = 200

        def submitter():
            for i in range(n):
                pool.submit(i)

        got = []
        got_lock = threading.Lock()
        done = threading.Event()

        def worker():
            while not done.is_set():
                job = pool.handoff("h", "r") or pool.claim("c")
                if job is None and not pool._queue:
                    done.set()
                    return
