                    with got_lock:
                        got.append(job)

        st = threading.Thread(target=submitter)
        ws = [threading.Thread(target=worker) for _ in range(3)]
        st.start()
        for t in ws:
            t.start()
        for t in ws:
            t.join(timeout=15)
        st.join(timeout=5)
        for t in ws:
            self.assertFalse(t.is_alive(), "worker did not finish in time")
        done.set()


if __name__ == "__main__":
    unittest.main(verbosity=2)

